-- Let me check if there's a specific anomaly score field somewhere that I'm missing
-- Check the investigation table for any score-related columns
SELECT * FROM investigation LIMIT 1;

-- Let me check what the actual type of transaction_pattern_category is
SELECT DISTINCT pg_typeof(r.network_behavior_analytics->>'transaction_pattern_category')
FROM riskanalysis r
LIMIT 1;

-- And also check if there are any NULL values
SELECT COUNT(*) FROM riskanalysis 
WHERE network_behavior_analytics->>'transaction_pattern_category' IS NULL;

-- Check exact values
SELECT DISTINCT network_behavior_analytics->>'transaction_pattern_category' as cat, length(network_behavior_analytics->>'transaction_pattern_category') as len
FROM riskanalysis;
